"""Build a portable review page; source JPEGs remain unchanged beneath SVG overlays.
Usage: python research/build_qumran_video_comparison.py /path/to/source-images
Required filenames are recorded in registration/qumran_video_annotations.json.
"""
import base64, hashlib, html, json, re, sys
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
source = Path(sys.argv[1])
data = json.loads((ROOT/'research/registration/qumran_video_annotations.json').read_text())

def panel(p):
    raw=(source/p['file']).read_bytes()
    assert hashlib.sha256(raw).hexdigest()==p['sha256'], p['file']
    shapes=[]
    for m in p['marks']:
        points=' '.join(f'{x},{y}' for x,y in m['points'])
        shapes.append(f'<polygon class="{m["status"]}" points="{points}"><title>{html.escape(m["label"])}</title></polygon>')
        x,y=m['tag']
        shapes.append(f'<g transform="translate({x} {y})"><circle r="22"/><text y="7">{m["id"]}</text></g>')
    uri='data:image/jpeg;base64,'+base64.b64encode(raw).decode()
    notes=''.join(f'<li><b>{m["id"]} · {html.escape(m["label"])}</b> {html.escape(m["note"])}</li>' for m in p['marks'])
    return f'''<section class="panel"><h2>{html.escape(p['title'])}</h2><svg role="img" aria-label="{html.escape(p['title'])}" viewBox="0 0 {p['width']} {p['height']}"><image href="{uri}" width="100%" height="100%"/><g class="overlays">{''.join(shapes)}</g></svg><p class="credit">{html.escape(p['credit'])} · <a href="{html.escape(p['url'])}">Source</a></p><ul>{notes}</ul></section>'''
plans=(ROOT/'public/research/entry21-comparison.html').read_text()
plans=re.findall(r'<svg viewBox=.*?</svg>',plans,re.S)[:2]
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Qumran · what the footage resolves</title><style>
*{box-sizing:border-box}body{margin:0;background:#292824;color:#302d27;font:16px/1.55 system-ui,sans-serif}main{max-width:1350px;margin:24px auto;background:#f3eddf;padding:clamp(20px,4vw,52px);box-shadow:0 12px 45px #0006}h1{font:clamp(34px,4vw,54px)/1.1 Georgia,serif;max-width:800px;margin:12px 0 22px}h2{font:24px/1.25 Georgia,serif;margin:0 0 16px}.eyebrow{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#895034}.intro{max-width:900px}.verdict{border-left:4px solid #936344;padding:10px 20px;background:#e7ddca}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:25px 0}.panel{min-width:0;background:#fcf8ee;border:1px solid #c7bba5;padding:20px}.wide{grid-column:1/-1}.panel svg{display:block;width:100%;height:auto}.credit{font-size:12px;color:#635c50}a{color:#704324}li{margin:9px 0}ul{padding-left:19px}.controls{position:sticky;top:0;background:#f3eddfed;padding:12px 0;z-index:2}button{font:inherit;padding:9px 16px;border:1px solid #7b6751;background:#fff9eb;border-radius:4px;cursor:pointer}button:focus-visible{outline:3px solid #157c86}.overlays polygon{fill:#55dfe822;stroke:#55dfe8;stroke-width:4}.overlays .probable{stroke:#ffe19a;fill:#ffe19a22;stroke-dasharray:10 7}.overlays circle{fill:#15383e;stroke:white;stroke-width:2}.overlays text{font:bold 20px system-ui;fill:white;text-anchor:middle}.hide .overlays{display:none}.channel{fill:none;stroke:#5c645c;stroke-width:3}.tunnel{fill:none;stroke:#343a35;stroke-width:9}.reconstruction{fill:none;stroke:#947953;stroke-width:2;stroke-dasharray:6 4}.basin{fill:#d6e2dd;stroke:#81948c;stroke-width:1.5}.wall{fill:none;stroke:#615647;stroke-width:5}.rock{fill:#c3af90;stroke:#786c59}.annotation{font:14px system-ui;fill:#554a3d}.leader,.scale{fill:none;stroke:#766957}.halo{fill:none}.dot{fill:#f6e6c7;stroke:#9a4528;stroke-width:1.5}.mark text{font:bold 11px system-ui;text-anchor:middle;fill:#79361e}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:12px;border-bottom:1px solid #c7bba5;text-align:left;vertical-align:top}.scroll{overflow:auto}.small{font-size:14px;color:#645d52}@media(max-width:760px){main{margin:0}.grid{grid-template-columns:1fr}.panel{padding:14px}}@media print{body{background:white}main{margin:0;box-shadow:none}.controls{display:none}.panel{break-inside:avoid}}
</style><main><div class="eyebrow">Copper Scroll · entries 20–23 · 28 September 2026</div><h1>Qumran: what the footage resolves</h1><p class="intro">The aerial sequence supplies gorge context and a probable cave match. Archival photographs identify a tunnel mouth more securely. The upstream intake, boulder and wall remain unconnected in the reviewed views.</p><p class="verdict"><b>Result:</b> retain the existing candidate order and low exact-feature confidence. None of these images identifies a Copper Scroll hiding place.</p><div class="controls"><button id="toggle" aria-pressed="true">Hide annotations</button> <span class="small">Solid cyan: visible outline · dashed amber: probable identity</span></div><div class="grid">PANELS</div><h2>Comparison with the two published plans</h2><p>Each redrawing retains its own source coordinate system. Perspective views above are not registered to these plans.</p><div class="grid"><section class="panel"><h2>Ilan–Amit, Fig. 1</h2>PLAN1<p class="small">1989, p. 283. A: visible intake, point 3. C: branch / short tunnel. D: long tunnel. The dashed basin-edge dam is a reconstruction.</p></section><section class="panel"><h2>Reeder–Jol, Fig. 4</h2>PLAN2<p class="small">2006, p. 229; survey in 2002. B: large rock below the pothole. The reported upstream wall is distinct from Ilan’s hypothetical main-wadi dam.</p></section></div><div class="scroll"><table><thead><tr><th>Proposed correspondence</th><th>Finding</th><th>Effect on identification</th></tr></thead><tbody><tr><td>Cave 28 ↔ drone, 01:20</td><td>Probable; opening and pale apron agree.</td><td>Orientation landmark only. No surveyed camera bearing.</td></tr><tr><td>Visible basin ↔ Ilan point 2</td><td>Unconfirmed; several basin floors occur in the gorge.</td><td>Keep the basin name and footprint unresolved.</td></tr><tr><td>Ilan point 3 ↔ Reeder collection ravine</td><td>Neither intake nor complete wall–pothole–rock sequence isolated in footage.</td><td>Same-sector hypothesis remains; no exact cross-plan match.</td></tr><tr><td>CJD979 ↔ Reeder Fig. 2 / Magen Fig. 87</td><td>High visual confidence in the same mouth; western attribution follows Magen’s text.</td><td>Supports candidate D’s landmark identity. Its role as the conduit’s head remains weak.</td></tr><tr><td>Rock ↔ channel ↔ north</td><td>Required anchors and grammatical referent unresolved.</td><td>No compass test, distance or ground footprint follows from the pixels.</td></tr></tbody></table></div><h2 style="margin-top:30px">What this leaves open</h2><p>Under a whole-conduit reading of entry 21, A remains the first feature to investigate. A branch-head reading gives C more weight. A northward approach to Sekakah requires a different test from a rock north of a channel. The sampled images settle none of these alternatives.</p><p>For entry 22, the generally eastern position of the long tunnel relative to Ilan’s basin is only a conditional fit: the reservoir’s name and the individual fissure remain unidentified. Entry 20 retains the heap/dam dispute; entry 23 still lacks secure distance endpoints.</p><p class="small">Manual outlines are image annotations, with unknown ground accuracy. The 01:38 marks follow visible edges only; concealed basin limits are omitted. Video inspected at 5-second intervals and at 1-second intervals from 01:15–01:45, plus selected full-size frames. Two watermarked stills are used here for source criticism. Capture date, camera calibration and coordinates are unknown.</p><p><a href="https://github.com/quadrin/AncientHebrewTexts/blob/main/copper_scroll/qumran_archival_photo_video_review.md">Research notes and source register</a></p></main><script>const b=document.getElementById('toggle');b.onclick=()=>{const hide=document.body.classList.toggle('hide');b.setAttribute('aria-pressed',String(!hide));b.textContent=hide?'Show annotations':'Hide annotations'};</script></html>'''
page=page.replace('PANELS',''.join(panel(p) for p in data['panels'])).replace('PLAN1',plans[0]).replace('PLAN2',plans[1])
# Static plan marks are labels here, not interactive buttons.
page=re.sub(r' role="button" tabindex="0" aria-label="Select candidate [A-D]"','',page)
out=ROOT/'public/research/qumran-video-comparison.html'
out.write_text(page)
print(out, out.stat().st_size)
